class Solution {
public:
    int bestClosingTime(std::string customers) {
        int cur_penalty = 0;
        for (char c : customers) if (c == 'Y') cur_penalty++;
        int min_penalty = cur_penalty;
        int best_hour = 0;
        for (int i = 0; i < (int)customers.size(); ++i) {
            if (customers[i] == 'Y') cur_penalty--;
            else cur_penalty++;
            if (cur_penalty < min_penalty) {
                min_penalty = cur_penalty;
                best_hour = i + 1;
            }
        }
        return best_hour;
    }
};

class Solution {
    public int bestClosingTime(String customers) {
        int curPenalty = 0;
        for (int i = 0; i < customers.length(); i++) {
            if (customers.charAt(i) == 'Y') curPenalty++;
        }
        int minPenalty = curPenalty;
        int bestHour = 0;
        for (int i = 0; i < customers.length(); i++) {
            if (customers.charAt(i) == 'Y') curPenalty--;
            else curPenalty++;
            if (curPenalty < minPenalty) {
                minPenalty = curPenalty;
                bestHour = i + 1;
            }
        }
        return bestHour;
    }
}

